CREATE FUNCTION cash_item(n int) RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_build_object('source_type','cash_rake_record','source_id',u(n))$$;
CREATE TABLE test_receipts(label text PRIMARY KEY,receipt jsonb);
SET test.fail_commission='true';
INSERT INTO test_receipts SELECT 'commission_fail',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(100)));
SELECT assert_true((SELECT receipt->>'ok'='0' AND receipt->>'failed'='1' AND receipt->>'blocked'='1' AND receipt->>'receipt_version'='3' FROM test_receipts WHERE label='commission_fail'),'commission exception is explicit durable refusal, never a successful credit');
SELECT assert_true((SELECT count(*) FROM accounting_cash_source_receipts)=1 AND (SELECT count(*) FROM accounting_cash_source_work WHERE status='blocked')=1,'source refusal and retry work commit together');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM agent_commissions) AND NOT EXISTS(SELECT 1 FROM accounting_cash_accrual_batches) AND NOT EXISTS(SELECT 1 FROM rakeback_stats_applied) AND NOT EXISTS(SELECT 1 FROM player_stats),'mid-hierarchy refusal rolls back every contributor and statistic');
SELECT assert_true(fn_cash_source_refusals_for_period(u(20),NULL,fn_union_week_start(now()),fn_union_week_start(now()+interval '8 days'))->>'count'='1','bank union refusal blocks its exact week');
SELECT assert_true(fn_cash_source_refusals_for_period(u(21),NULL,fn_union_week_start(now()),fn_union_week_start(now()+interval '8 days'))->>'status'='ready','known bank union refusal does not stop another union');
SELECT assert_true(fn_cash_source_refusals_for_period(NULL,u(40),fn_union_week_start(now()),fn_union_week_start(now()+interval '8 days'))->>'status'='ready','union refusal does not stop an unrelated standalone club');
SET test.fail_commission='false';
SET test.fail_stats='true';
INSERT INTO test_receipts SELECT 'stats_fail',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(100)));
SELECT assert_true((SELECT receipt->>'blocked'='1' FROM test_receipts WHERE label='stats_fail') AND NOT EXISTS(SELECT 1 FROM agent_commissions) AND NOT EXISTS(SELECT 1 FROM rakeback_stats_applied),'stats failure rolls canonical commission liability and stats marker back');
SET test.fail_stats='false';
SET test.fail_queue='true';
INSERT INTO test_receipts SELECT 'queue_fail',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(100)));
SELECT assert_true((SELECT receipt->>'blocked'='1' FROM test_receipts WHERE label='queue_fail') AND NOT EXISTS(SELECT 1 FROM agent_commissions) AND NOT EXISTS(SELECT 1 FROM player_stats) AND NOT EXISTS(SELECT 1 FROM rakeback_stats_applied),'downstream durable queue failure rolls the full source transaction back');
SET test.fail_queue='false';
CREATE TRIGGER test_cash_ack_failure BEFORE INSERT ON accounting_cash_source_receipts FOR EACH ROW EXECUTE FUNCTION test_cash_ack_failure();
CREATE TRIGGER test_cash_work_failure BEFORE INSERT ON accounting_cash_source_work FOR EACH ROW EXECUTE FUNCTION test_cash_work_failure();
SET test.fail_ack='true';
INSERT INTO test_receipts SELECT 'ack_fail',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(100)));
SELECT assert_true((SELECT receipt->>'failed'='1' AND receipt->>'blocked'='0' AND receipt->'receipts'='[]'::jsonb FROM test_receipts WHERE label='ack_fail') AND NOT EXISTS(SELECT 1 FROM agent_commissions) AND NOT EXISTS(SELECT 1 FROM player_stats),'missing durable acknowledgement is an unhandled failure and rolls source work back');
SET test.fail_ack='false';
SET test.fail_work='true';
INSERT INTO test_receipts SELECT 'work_fail',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(100)));
SELECT assert_true((SELECT receipt->>'failed'='1' AND receipt->>'blocked'='0' FROM test_receipts WHERE label='work_fail') AND NOT EXISTS(SELECT 1 FROM agent_commissions) AND (SELECT count(*) FROM accounting_cash_source_receipts)=3,'failed work linkage cannot leave an orphan success receipt or partial source');
SET test.fail_work='false';
INSERT INTO test_receipts SELECT 'ready',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(100)));
SELECT assert_true((SELECT receipt->>'ok'='1' AND receipt->>'failed'='0' AND receipt->>'blocked'='0' AND jsonb_array_length(receipt->'receipts'->0->'credits')=2 FROM test_receipts WHERE label='ready'),'one source success covers every contributor');
SELECT assert_true((SELECT count(*) FROM agent_commissions)=6 AND (SELECT sum(amount) FROM agent_commissions)=7.75 AND (SELECT sum(hands_played) FROM player_stats)=2 AND (SELECT sum(total_rake) FROM player_stats)=10,'actual original stats writer applies exactly one hand and each original rake share');
SELECT assert_true((SELECT count(*) FROM accounting_period_recompute_requests WHERE club_id=u(10) AND status='pending')=1,'source acknowledgement durably queues the existing full-week calculation');
SELECT assert_true(fn_cash_source_refusals_for_period(u(20),NULL,fn_union_week_start(now()),fn_union_week_start(now()+interval '8 days'))->>'count'='0','resolved source leaves the failure gate through its latest durable receipt');
INSERT INTO test_receipts SELECT 'duplicate',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(100)));
SELECT assert_true((SELECT receipt->'receipts'->0->>'duplicate'='true' FROM test_receipts WHERE label='duplicate') AND (SELECT count(*) FROM accounting_cash_source_receipts)=4 AND (SELECT sum(total_rake) FROM player_stats)=10 AND (SELECT count(*) FROM agent_commissions)=6,'replay returns the same durable acknowledgement without recredit or duplicate stats');
SELECT assert_true(refuses('UPDATE accounting_cash_source_receipts SET reason=''changed''','55000'),'durable source attempts cannot be rewritten');
SELECT assert_true(refuses('TRUNCATE accounting_cash_source_receipts CASCADE','55000'),'durable source attempts cannot be truncated');
SELECT assert_true(NOT has_table_privilege('service_role','accounting_cash_source_receipts','INSERT') AND NOT has_table_privilege('service_role','accounting_cash_source_work','UPDATE') AND NOT has_function_privilege('service_role','fn_process_cash_accounting_source(uuid)','EXECUTE'),'service cannot fabricate or mark a source acknowledgement');
SELECT assert_true(NOT has_function_privilege('authenticated','fn_credit_agent_commissions_batch(jsonb)','EXECUTE') AND NOT has_function_privilege('anon','fn_retry_cash_accounting_sources(integer)','EXECUTE'),'public callers cannot trigger source retries');
INSERT INTO rake_records(id,hand_id,club_id,rake_amount,created_at,metadata) VALUES(u(110),u(111),u(20),2,clock_timestamp(),jsonb_build_object('accounting_source_version',2,'union_id',u(20),'is_private',false)),(u(120),u(121),u(40),3,clock_timestamp(),jsonb_build_object('accounting_source_version',2,'union_id',NULL,'is_private',true));
INSERT INTO rake_attributions VALUES(u(122),u(120),u(121),u(41),u(40),3);
INSERT INTO test_receipts SELECT 'mixed',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(110),cash_item(120)));
SELECT assert_true((SELECT receipt->>'ok'='1' AND receipt->>'blocked'='1' AND receipt->>'failed'='1' FROM test_receipts WHERE label='mixed') AND (SELECT total_rake FROM player_stats WHERE user_id=u(41) AND club_id=u(40))=3,'missing source attribution cannot stop the next healthy book in the same batch');
SELECT assert_true((SELECT scope->>'kind'='union' AND scope->>'id'=u(20)::text FROM accounting_cash_source_receipts r JOIN accounting_cash_source_work w ON w.receipt_id=r.id WHERE w.rake_record_id=u(110)),'missing player attribution still retains its proven actual bank union');
-- Fixture adds the actual missing allocation, never historical rates or payments.
INSERT INTO rake_attributions VALUES(u(112),u(110),u(111),u(12),u(10),2);
UPDATE accounting_cash_source_work SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE rake_record_id=u(110);
INSERT INTO test_receipts SELECT 'retry',fn_retry_cash_accounting_sources(50);
SELECT assert_true((SELECT receipt->>'ok'='1' AND receipt->>'failed'='0' FROM test_receipts WHERE label='retry') AND (SELECT total_rake FROM player_stats WHERE user_id=u(12))=6,'due retry restores original commissions, stats, and period queue after the global cursor could have moved');
SELECT assert_true((SELECT count(*) FROM agent_commissions)=9 AND (SELECT status FROM accounting_cash_source_work WHERE rake_record_id=u(110))='accrued','retry pays each immutable source liability once');
SELECT assert_true(fn_retry_cash_accounting_sources(50)->>'ok'='0','completed source is no longer in the retry scan');
INSERT INTO rake_records(id,hand_id,club_id,rake_amount,created_at,metadata) VALUES(u(130),NULL,u(40),1,'2026-09-07T08:00Z','{}');
INSERT INTO test_receipts SELECT 'unknown',fn_credit_agent_commissions_batch(jsonb_build_array(cash_item(130)));
SELECT assert_true((SELECT receipt->>'blocked'='1' AND receipt->'receipts'->0->'scope'->>'kind'='unknown' FROM test_receipts WHERE label='unknown'),'missing historical hand and bank has durable unknown-scope refusal');
SELECT assert_true(fn_cash_source_refusals_for_period(u(20),NULL,'2026-09-07T07:00Z','2026-09-14T07:00Z')->>'count'='1' AND fn_cash_source_refusals_for_period(NULL,u(40),'2026-09-07T07:00Z','2026-09-14T07:00Z')->>'count'='1','unprovable historical private coordinator conservatively blocks that week');
SELECT assert_true(fn_cash_source_refusals_for_period(u(20),NULL,fn_union_week_start(now()),fn_union_week_start(now()+interval '8 days'))->>'count'='0','unknown history does not block a different accounting week');
SELECT assert_true((fn_credit_agent_commissions_batch(jsonb_build_array(jsonb_build_object('source_type','rake_settlement','source_id',u(101),'user_id',u(12),'club_id',u(10),'rake_credit',4)))->>'ok')='1' AND (SELECT sum(total_rake) FROM player_stats)=15,'legacy batch input delegates the same acknowledged whole hand');
SELECT assert_true((fn_credit_agent_commissions_batch(jsonb_build_array(jsonb_build_object('source_type','rake_settlement','source_id',u(101),'user_id',u(12),'club_id',u(40),'rake_credit',4)))->>'blocked')='0','unproven caller input is not fabricated into a durable source refusal');
SET test.engine='false';
SELECT assert_true(refuses('SELECT fn_retry_cash_accounting_sources(1)','42501') AND refuses('SELECT fn_credit_agent_commissions_batch(''[]'')','42501'),'both external batch doors authenticate the engine');
SET test.engine='true';
SELECT assert_true(refuses('SELECT fn_retry_cash_accounting_sources(201)','22023'),'retry cannot exceed the bounded source page');
-- Keep one unprocessed valid source for the competing-caller proof.
INSERT INTO rake_records(id,hand_id,club_id,rake_amount,created_at,metadata) VALUES(u(140),u(141),u(20),1,clock_timestamp(),jsonb_build_object('accounting_source_version',2,'union_id',u(20),'is_private',false));
INSERT INTO rake_attributions VALUES(u(142),u(140),u(141),u(12),u(10),1);
